import type { CardCheck } from '@/lib/flashcard-check-core'

/**
 * Card-check questions for the cards of `mcat-physics-mechanics-mcat`: one per card, keyed by the
 * card's exact front text. Each asks the student to use the card's idea in a
 * new situation. Gate: scripts/flashcard-checks/validate.ts.
 */
const r = String.raw

export const checks: Record<string, CardCheck> = {
  [r`What are the conditions for full equilibrium?`]: {
    question: r`A uniform meter stick lies at rest on a frictionless table. Two 5 N forces are applied at its opposite ends, perpendicular to the stick and pointing in opposite directions. Which statement describes the stick?`,
    options: [r`Net force is zero and net torque is zero, so it is in equilibrium`, r`Net force is zero but net torque is not, so it is not in equilibrium`, r`Net torque is zero but net force is not, so it is not in equilibrium`, r`Net force and net torque are both nonzero, so it is not in equilibrium`],
    correctAnswer: 1,
    explanation: r`The two forces are equal and opposite, so they sum to zero, but both turn the stick the same way about its center, so the net torque is not zero and the stick starts to spin. Full equilibrium needs both sums to be zero. Calling it equilibrium checks only the forces, and the other two statements miss that the forces cancel.`,
  },
  [r`Why do horizontally launched and dropped objects land together?`]: {
    question: r`Two marbles roll off the edge of a level table 1.25 m high, one at 2 m/s and the other at 6 m/s. Taking g = 10 m/s² and ignoring air resistance, how long does each marble spend in the air (slower marble first)?`,
    options: [r`0.50 s and 0.50 s`, r`0.50 s and 1.50 s`, r`1.50 s and 0.50 s`, r`0.50 s and 0.17 s`],
    correctAnswer: 0,
    explanation: r`Both marbles leave with zero vertical velocity and fall 1.25 m under g, so each takes t = √(2h/g) = √0.25 = 0.50 s. Horizontal speed changes only where they land, not when. The answers with 1.50 s or 0.17 s scale the fall time by the ratio of the horizontal speeds, which treats the two motions as linked.`,
  },
  [r`List the main kinematic equations.`]: {
    question: r`A cyclist moving at 4 m/s speeds up at a steady 2 m/s² while covering 12 m. No time is given. What is the cyclist's speed at the end of the 12 m?`,
    options: [r`6.9 m/s`, r`10 m/s`, r`8 m/s`, r`28 m/s`],
    correctAnswer: 2,
    explanation: r`With no time given, use v² = v₀² + 2ad = 16 + 2(2)(12) = 64, so v = 8 m/s. Leaving out v₀² gives √48 = 6.9 m/s. Getting 10 m/s comes from wrongly taking the time as 12/4 = 3 s, and 28 m/s comes from putting the distance where the time belongs in v = v₀ + at.`,
  },
  [r`Give the components of gravity on an incline of angle $\theta$.`]: {
    question: r`A 5 kg crate sits on a ramp inclined at 37° (sin 37° = 0.60, cos 37° = 0.80). Taking g = 10 m/s², what are the components of the crate's weight along the ramp and into the ramp?`,
    options: [r`40 N along the ramp, 30 N into the ramp`, r`30 N along the ramp, 50 N into the ramp`, r`50 N along the ramp, 40 N into the ramp`, r`30 N along the ramp, 40 N into the ramp`],
    correctAnswer: 3,
    explanation: r`The weight is 50 N. Along the ramp it is mg sin θ = 50 × 0.60 = 30 N, and into the ramp it is mg cos θ = 50 × 0.80 = 40 N. Swapping sine and cosine gives 40 N along and 30 N into the ramp. The answers that contain 50 N use the full weight as one of the components.`,
  },
  [r`Compare static and kinetic friction.`]: {
    question: r`A 10 kg crate rests on a level floor with μs = 0.50 and μk = 0.30 (g = 10 m/s²). A horizontal push is raised slowly until the crate just breaks free, then held at that value. What is the crate's acceleration once it is sliding?`,
    options: [r`0 m/s²`, r`2 m/s²`, r`3 m/s²`, r`5 m/s²`],
    correctAnswer: 1,
    explanation: r`The push needed to start motion is μs·N = 0.50 × 100 = 50 N. Once sliding, friction drops to μk·N = 30 N, so the net force is 20 N and a = 20/10 = 2 m/s². Zero assumes friction stays at its static maximum, 5 m/s² ignores friction altogether, and 3 m/s² divides the kinetic friction force by the mass.`,
  },
  [r`Give centripetal acceleration and force.`]: {
    question: r`A 0.5 kg puck on a frictionless table is tied to a 2 m string and moves in a circle at a steady 4 m/s. What is the tension in the string?`,
    options: [r`1 N`, r`8 N`, r`4 N`, r`16 N`],
    correctAnswer: 2,
    explanation: r`The tension is the centripetal force: mv²/r = 0.5 × 16 / 2 = 4 N. Forgetting to square the speed gives 1 N, leaving out the mass gives the acceleration value 8, and multiplying by the radius instead of dividing gives 16 N.`,
  },
  [r`Define torque and when it is maximized.`]: {
    question: r`A door swings on hinges along one edge. Which push produces the largest torque about the hinges?`,
    options: [r`20 N at 0.8 m from the hinges, perpendicular to the door`, r`30 N at 0.4 m from the hinges, perpendicular to the door`, r`40 N at 0.6 m from the hinges, at 30° to the door surface`, r`50 N at 0.8 m from the hinges, directed straight at the hinges`],
    correctAnswer: 0,
    explanation: r`Torque is rF sin θ. The 20 N push gives 0.8 × 20 = 16 N·m. The 30 N push gives only 12 N·m because it acts closer to the hinges, the 40 N push gives 0.6 × 40 × 0.5 = 12 N·m because of its angle, and the 50 N push gives zero because its line of action passes through the pivot. A large force does not help without lever arm and a perpendicular direction.`,
  },
  [r`What is terminal velocity?`]: {
    question: r`A 70 kg skydiver has stopped speeding up and now falls at a steady 50 m/s. Taking g = 10 m/s², what is the size of the drag force on the skydiver?`,
    options: [r`0 N`, r`1400 N`, r`3500 N`, r`700 N`],
    correctAnswer: 3,
    explanation: r`At a steady speed the acceleration is zero, so drag must exactly balance the weight: 70 × 10 = 700 N. Zero is the net force, not the drag force. 3500 N multiplies mass by speed, which is momentum, and 1400 N would make the net force upward so the skydiver would be slowing.`,
  },
  [r`Kinetic energy equals:`]: {
    question: r`With the brakes locked, a car travelling at 15 m/s skids 20 m before stopping. With the same braking force, how far does it skid from 45 m/s?`,
    options: [r`60 m`, r`90 m`, r`180 m`, r`540 m`],
    correctAnswer: 2,
    explanation: r`The brakes must remove all the kinetic energy, and ½mv² grows with the square of speed. Tripling the speed makes the energy, and so the stopping distance, 9 times as large: 9 × 20 = 180 m. Getting 60 m treats the distance as proportional to speed, 90 m applies only half of the factor of 9, and 540 m cubes the factor of 3.`,
  },
  [r`A 2 kg ball at 5 m/s has momentum of:`]: {
    question: r`A 60 kg sprinter runs at 9 m/s while a 1200 kg car rolls at 0.5 m/s. Which has the larger momentum?`,
    options: [r`The car: 600 kg·m/s versus 540 kg·m/s`, r`The sprinter: 2430 kg·m/s versus 150 kg·m/s`, r`The sprinter: 540 kg·m/s versus 300 kg·m/s`, r`Neither: both have exactly 540 kg·m/s`],
    correctAnswer: 0,
    explanation: r`Momentum is mv: 60 × 9 = 540 kg·m/s for the sprinter and 1200 × 0.5 = 600 kg·m/s for the car, so the slow car has more. The 2430 and 150 figures are kinetic energies in joules, from ½mv². The 300 figure halves the car's momentum for no reason, and the two values are not equal.`,
  },
  [r`A projectile is launched at 30° above the horizontal at 20 m/s. What is the horizontal component of its initial velocity?`]: {
    question: r`A ball is kicked at 30 m/s at 60° above level ground (cos 60° = 0.50, sin 60° = 0.87) and lands 5.2 s later. Ignoring air resistance, how far from the kick does it land?`,
    options: [r`39 m`, r`78 m`, r`135 m`, r`156 m`],
    correctAnswer: 1,
    explanation: r`The horizontal velocity is 30 × cos 60° = 15 m/s and stays constant, so the range is 15 × 5.2 = 78 m. Using the full 30 m/s gives 156 m, using the sine (the vertical component, 26 m/s) gives 135 m, and 39 m halves the correct result.`,
  },
  [r`Two objects have equal kinetic energy but different masses. The heavier one has:`]: {
    question: r`A 1 kg cart and a 4 kg cart each have 8 J of kinetic energy. What are their momenta (1 kg cart first)?`,
    options: [r`4 kg·m/s and 4 kg·m/s`, r`8 kg·m/s and 4 kg·m/s`, r`4 kg·m/s and 16 kg·m/s`, r`4 kg·m/s and 8 kg·m/s`],
    correctAnswer: 3,
    explanation: r`p = √(2m·KE): √(2 × 1 × 8) = 4 kg·m/s and √(2 × 4 × 8) = 8 kg·m/s. At equal kinetic energy momentum grows with the square root of mass, so four times the mass gives twice the momentum. Equal momenta confuses the two quantities, 16 scales with mass directly, and the reversed pair gives the lighter cart more.`,
  },
  [r`A book rests on a table. The reaction force to its weight (per the third law) acts on:`]: {
    question: r`A lamp hangs at rest from a ceiling by a cord. The cord pulls upward on the lamp. What is the third-law reaction to that force?`,
    options: [r`The Earth pulling downward on the lamp`, r`The ceiling pulling upward on the cord`, r`The lamp pulling downward on the cord`, r`The lamp pulling upward on the Earth`],
    correctAnswer: 2,
    explanation: r`A reaction force swaps the two objects: the cord pulls up on the lamp, so the lamp pulls down on the cord. The Earth's pull on the lamp balances the cord's pull here, but it acts on the same object and is a different interaction. The lamp's pull on the Earth is the partner of the lamp's weight, and the ceiling's pull on the cord pairs with the cord's pull on the ceiling.`,
  },
  [r`Equilibrium requires:`]: {
    question: r`A light plank balances on a pivot at its center. A 300 N child sits 2.0 m to the left of the pivot. Where must a 400 N child sit on the right for the plank to stay level and at rest, and how hard does the pivot push up?`,
    options: [r`1.5 m from the pivot; the pivot pushes up with 700 N`, r`1.5 m from the pivot; the pivot pushes up with 100 N`, r`2.0 m from the pivot; the pivot pushes up with 700 N`, r`2.7 m from the pivot; the pivot pushes up with 700 N`],
    correctAnswer: 0,
    explanation: r`Zero net torque about the pivot needs 300 × 2.0 = 400 × d, so d = 1.5 m. Zero net force needs the pivot to hold up both weights, 700 N. A support force of 100 N subtracts the weights, sitting at 2.0 m leaves a net torque from the heavier child, and 2.7 m inverts the ratio of the weights.`,
  },
  [r`A 1000 kg car accelerates from 0 to 30 m/s in 6 seconds. What is the average net force?`]: {
    question: r`An 80 kg cyclist (rider plus bicycle) slows from 12 m/s to 4 m/s in 4 s. What is the size of the average net force during the braking?`,
    options: [r`240 N`, r`320 N`, r`640 N`, r`160 N`],
    correctAnswer: 3,
    explanation: r`The acceleration is Δv/Δt = (4 − 12)/4 = −2 m/s², so the net force has size 80 × 2 = 160 N, directed against the motion. Using the starting speed instead of the change gives 240 N, multiplying mass by the final speed or by the time gives 320 N, and 640 N is the momentum change, which has not yet been divided by the time.`,
  },
  [r`Why does friction on the drive tires point forward for an accelerating car?`]: {
    question: r`A person starts walking forward on level ground and the shoe does not slip. While the back foot pushes off, the friction force from the ground on that foot is:`,
    options: [r`kinetic and directed forward`, r`static and directed forward`, r`static and directed backward`, r`kinetic and directed backward`],
    correctAnswer: 1,
    explanation: r`The foot pushes backward on the ground, so by the third law the ground pushes forward on the foot, and this forward force is what accelerates the walker. The sole is not sliding over the ground, so the friction is static. The backward answers assume friction always opposes the body's motion, and the kinetic answers would need the shoe to be slipping.`,
  },
  [r`Is an astronaut orbiting Earth actually weightless?`]: {
    question: r`At the altitude of a space station, g is 8.7 m/s². A 70 kg astronaut stands on a bathroom scale inside the orbiting station. What are the gravitational force on the astronaut and the scale reading?`,
    options: [r`Zero gravitational force; the scale reads zero`, r`About 610 N of gravity; the scale reads 610 N`, r`About 610 N of gravity; the scale reads zero`, r`About 700 N of gravity; the scale reads 700 N`],
    correctAnswer: 2,
    explanation: r`Gravity still acts: 70 × 8.7 is about 610 N, and it is this force that keeps the astronaut in orbit. The astronaut and the scale are both in free fall, so they do not press on each other and the scale reads zero. Zero gravity confuses apparent weight with true weight, and a nonzero scale reading would need a normal force that free fall does not supply.`,
  },
  [r`When may force magnitudes be added directly instead of by components?`]: {
    question: r`A sled is pulled by one rope with 30 N toward the east and by a second rope with 40 N toward the north. A student adds the numbers and reports a net pull of 70 N. What is the correct net pull, and why?`,
    options: [r`50 N, because perpendicular forces add by components`, r`70 N, because force magnitudes always add directly`, r`10 N, because the two pulls partly cancel each other`, r`35 N, because the net force is the average of the two`],
    correctAnswer: 0,
    explanation: r`Magnitudes add directly only when forces lie along the same line. These pulls are perpendicular, so the net force is √(30² + 40²) = 50 N. The 70 N result would be right only if both ropes pulled the same way, 10 N only if they pulled in opposite directions, and averaging forces has no physical basis.`,
  },
  [r`Center of mass versus center of gravity: when do they differ?`]: {
    question: r`A 1 m rod is much denser at one end than the other. It is balanced on a finger in an ordinary laboratory. How do its center of mass and center of gravity compare?`,
    options: [r`Different points, because the rod's mass is uneven`, r`Same point, but only while the rod is horizontal`, r`Different points, because weight depends on mass`, r`Same point, because g is uniform along the rod`],
    correctAnswer: 3,
    explanation: r`The two points separate only when the gravitational field differs from one part of the object to another. Across a 1 m rod in a lab, g is the same everywhere, so the weight acts at the center of mass. Uneven mass moves both points together toward the dense end, and the orientation of the rod makes no difference.`,
  },
  [r`Why does mass distribution change how fast an object rolls down a ramp?`]: {
    question: r`A small 1 kg solid sphere and a large 5 kg hoop are released together from rest at the top of the same ramp and roll without slipping. Which reaches the bottom first, and why?`,
    options: [r`The hoop, because its larger mass gives a larger pull`, r`The sphere, because less of its energy goes into spin`, r`The hoop, because its larger radius covers more ground`, r`They tie, because all objects fall at the same rate`],
    correctAnswer: 1,
    explanation: r`The hoop has all its mass far from the axis, so a larger share of the released potential energy becomes rotation and less becomes forward motion. The sphere keeps more for translation and wins. Mass and radius cancel out of the result, so neither helps the hoop, and the equal-fall rule applies to free fall, not to rolling.`,
  },
  [r`Translational equilibrium means {{c1::$\Sigma F = 0$}}; rotational equilibrium means {{c1::$\Sigma \tau = 0$}}.`]: {
    question: r`Which of these objects is in translational equilibrium?`,
    options: [r`A ball at the top of its flight, momentarily at rest`, r`A car rounding a curve at a steady 20 m/s`, r`A skydiver falling straight down at a steady 50 m/s`, r`A sled slowing down as it slides over level snow`],
    correctAnswer: 2,
    explanation: r`Translational equilibrium means zero net force, so zero acceleration, and a steady speed in a straight line qualifies even though the object is moving. The ball at its peak has zero velocity but still accelerates at g. The car's direction is changing, so it has a net inward force, and the slowing sled has a net backward force.`,
  },
  [r`Centripetal acceleration equals {{c1::$v^2/r$}} and always points {{c1::toward the center}}.`]: {
    question: r`A car heading due north at 20 m/s is rounding a curve of radius 100 m. The center of the curve lies due east of the car. What is the car's acceleration at this instant?`,
    options: [r`4 m/s² toward the east`, r`4 m/s² toward the north`, r`4 m/s² toward the west`, r`0.2 m/s² toward the east`],
    correctAnswer: 0,
    explanation: r`The size is v²/r = 400/100 = 4 m/s², and it points at the center of the curve, which is east. North is the direction of the velocity, not of the acceleration. West points away from the center, the direction of the imagined centrifugal push, and 0.2 m/s² comes from v/r without squaring the speed.`,
  },
  [r`A machine can reduce the required {{c1::force}} but never the required {{c1::work}}.`]: {
    question: r`An ideal lever lets a worker raise a 900 N rock by 0.10 m while pushing down with only 150 N. How far must the worker's end of the lever move?`,
    options: [r`0.10 m`, r`0.02 m`, r`6.0 m`, r`0.60 m`],
    correctAnswer: 3,
    explanation: r`An ideal machine does not reduce the work: 900 N × 0.10 m = 90 J must equal 150 N × d, so d = 0.60 m. The force is cut by a factor of 6, so the distance grows by a factor of 6. Equal distances would mean less work in than out, 0.02 m divides by 6 instead of multiplying, and 6.0 m has a misplaced decimal.`,
  },
  [r`Mechanical advantage equals {{c1::$F_{out}/F_{in}$}}; for a lever it equals {{c1::the ratio of lever arms}}.`]: {
    question: r`On a crowbar, the worker pushes 1.2 m from the fulcrum and the load sits 0.2 m from the fulcrum on the other side. Because of friction, a 100 N push lifts only a 480 N load. What are the ideal and actual mechanical advantages?`,
    options: [r`Ideal 4.8, actual 6`, r`Ideal 6, actual 4.8`, r`Ideal 6, actual 6`, r`Ideal 0.17, actual 0.21`],
    correctAnswer: 1,
    explanation: r`The ideal value is the ratio of lever arms, 1.2/0.2 = 6. The actual value is the ratio of real forces, 480/100 = 4.8, which is smaller because friction wastes some of the input. Swapping the two would put the real machine above the ideal one, equal values ignore the friction, and 0.17 and 0.21 invert both ratios.`,
  },
  [r`Newton's third-law pairs always act on {{c1::two different objects}} and are {{c1::equal and opposite}}.`]: {
    question: r`On frictionless ice, a 60 kg skater pushes a 30 kg skater with a force of 90 N. What force acts on the 60 kg skater during the push, and what is her acceleration?`,
    options: [r`90 N backward; she accelerates at 1.5 m/s²`, r`45 N backward; she accelerates at 0.75 m/s²`, r`90 N backward; she accelerates at 3.0 m/s²`, r`180 N backward; she accelerates at 3.0 m/s²`],
    correctAnswer: 0,
    explanation: r`The pair of forces is equal and opposite and acts on the two different skaters, so she feels 90 N backward and a = 90/60 = 1.5 m/s². The forces are equal even though the masses differ, so 45 N and 180 N are wrong. An acceleration of 3.0 m/s² belongs to the 30 kg skater: equal forces do not mean equal accelerations.`,
  },
  [r`A uniform beam rests on two supports. Where does its weight act in the torque equation?`]: {
    question: r`A uniform 6 m beam weighing 300 N lies on two supports, one under its left end and one 4 m from the left end. What upward force does each support provide?`,
    options: [r`150 N at the left end and 150 N at the other support`, r`100 N at the left end and 200 N at the other support`, r`75 N at the left end and 225 N at the other support`, r`225 N at the left end and 75 N at the other support`],
    correctAnswer: 2,
    explanation: r`The beam's weight acts at its center, 3 m from the left end. Torques about the left end: 300 × 3 = F × 4, so the second support gives 225 N and the left end gives the remaining 75 N. Equal forces would need the supports to be symmetric about the center, 100 N and 200 N splits the weight by the 2 m and 4 m lengths, and the reversed pair puts the larger force on the support farther from the center.`,
  },
  [r`The center of mass of a two-mass system lies {{c1::closer to the heavier mass}}.`]: {
    question: r`A 2 kg mass sits at x = 0 and a 6 kg mass sits at x = 4 m. Where is the center of mass of the pair?`,
    options: [r`x = 1 m`, r`x = 2 m`, r`x = 2.5 m`, r`x = 3 m`],
    correctAnswer: 3,
    explanation: r`x = (2 × 0 + 6 × 4)/(2 + 6) = 24/8 = 3 m, three quarters of the way toward the heavier mass. The midpoint, 2 m, ignores the masses. Putting it at 1 m weights the position toward the lighter mass, and 2.5 m has no basis in the mass-weighted average.`,
  },
  [r`Which lever class has the fulcrum in the middle, and which always has MA below 1?`]: {
    question: r`In which tool is the effort applied between the fulcrum and the load, so that its mechanical advantage is always below 1?`,
    options: [r`A seesaw with a rider seated at each end`, r`Tweezers squeezed partway along their arms`, r`A crowbar prying up a nailed-down board`, r`A wheelbarrow lifted by its two handles`],
    correctAnswer: 1,
    explanation: r`Tweezers are joined at one end (the fulcrum), squeezed in the middle and grip at the tips, so the effort arm is shorter than the load arm: a third-class lever. The seesaw and the crowbar have the fulcrum in the middle, which is first class. The wheelbarrow has the load in the middle, which is second class and gives an advantage above 1.`,
  },
  [r`If Earth's radius doubled with mass unchanged, what happens to surface g?`]: {
    question: r`A planet has twice Earth's mass and twice Earth's radius. Taking g = 10 m/s² at Earth's surface, what is the surface gravitational acceleration on this planet?`,
    options: [r`5 m/s²`, r`2.5 m/s²`, r`10 m/s²`, r`20 m/s²`],
    correctAnswer: 0,
    explanation: r`g = GM/r², so doubling the mass doubles g and doubling the radius cuts it to a quarter: 10 × 2/4 = 5 m/s². Getting 2.5 m/s² uses only the radius change, 10 m/s² treats the radius as if it were not squared, and 20 m/s² uses only the mass change.`,
  },
  [r`Near a surface gravitational PE is {{c1::$mgh$}}, but at astronomical distances it is {{c1::$-GMm/r$}}.`]: {
    question: r`A satellite in orbit at distance r from a planet's center has gravitational potential energy −8 MJ. It is moved to an orbit at distance 2r. What is its potential energy there?`,
    options: [r`−16 MJ, a decrease in potential energy`, r`−4 MJ, a decrease in potential energy`, r`−4 MJ, an increase in potential energy`, r`−2 MJ, an increase in potential energy`],
    correctAnswer: 2,
    explanation: r`U = −GMm/r, so doubling r halves the size of U: −4 MJ. That value is less negative, so the energy has gone up, as it must when moving away from the planet. Calling −4 MJ a decrease reads the smaller number as less energy, −16 MJ makes U grow with distance, and −2 MJ uses the inverse-square rule that belongs to force.`,
  },
  [r`Tension in an ideal massless rope over a frictionless pulley is {{c1::the same everywhere}}.`]: {
    question: r`A 2 kg block on a frictionless table is tied by a light string, over an ideal pulley, to a hanging 3 kg block. The system accelerates at 6 m/s² (g = 10 m/s²). What is the tension in the horizontal and vertical parts of the string?`,
    options: [r`12 N horizontal and 30 N vertical`, r`20 N horizontal and 30 N vertical`, r`30 N in both parts of the string`, r`12 N in both parts of the string`],
    correctAnswer: 3,
    explanation: r`An ideal string over an ideal pulley has one tension throughout. From the 2 kg block, T = ma = 2 × 6 = 12 N, and the hanging block agrees: 30 − 12 = 18 N = 3 × 6. A tension of 30 N would leave the hanging block with no net force, and 20 N is the weight of the block on the table, which the table supports.`,
  },
  [r`Two perpendicular vectors of equal magnitude $V$ give a resultant of {{c1::$V\sqrt{2}$}}.`]: {
    question: r`Two ropes each pull on a ring with 100 N. The angle between the ropes is opened from 0° to 90°. How does the net pull on the ring change?`,
    options: [r`From 200 N to 100 N`, r`From 200 N to about 141 N`, r`From 100 N to about 141 N`, r`From 200 N to zero`],
    correctAnswer: 1,
    explanation: r`Parallel pulls add directly to 200 N. At right angles they combine by the Pythagorean theorem: 100√2, about 141 N. A drop to 100 N forgets that both ropes still contribute, a start of 100 N ignores one rope, and zero happens only when the ropes pull in opposite directions.`,
  },
  [r`Why is the biceps force so much larger than the weight held in the hand?`]: {
    question: r`A forearm is held level with a 20 N ball in the hand, 32 cm from the elbow. The biceps attaches 4 cm from the elbow and pulls straight up. Ignoring the forearm's own weight, what force must the biceps supply?`,
    options: [r`2.5 N`, r`20 N`, r`160 N`, r`640 N`],
    correctAnswer: 2,
    explanation: r`Balancing torques about the elbow: F × 4 cm = 20 N × 32 cm, so F = 160 N, eight times the load, because the muscle's lever arm is eight times shorter. Getting 2.5 N inverts the ratio of lever arms, 20 N assumes equal arms, and 640 N multiplies force by distance without dividing by the muscle's arm.`,
  },
  [r`In uniform circular motion, speed is constant but {{c1::velocity and acceleration}} constantly change direction.`]: {
    question: r`A puck moves around a circle at a steady 3 m/s. Compare its motion at one point with its motion half a revolution later.`,
    options: [r`The speed is unchanged, but the velocity has changed by 6 m/s`, r`The speed and the velocity are both the same as before`, r`The speed is unchanged, but the velocity has changed by 3 m/s`, r`The speed has changed by 6 m/s, but the velocity is the same`],
    correctAnswer: 0,
    explanation: r`Speed stays at 3 m/s, but velocity is a vector tangent to the circle, and after half a turn it points the opposite way. The change is from +3 to −3 m/s, a difference of 6 m/s. Saying nothing changed treats velocity as speed, a 3 m/s change forgets the reversal, and the last statement swaps the two terms.`,
  },
  [r`A block hangs from two symmetric ropes. How does rope angle affect tension?`]: {
    question: r`A 100 N sign hangs at rest from two ropes. Each rope makes a 30° angle with the horizontal ceiling (sin 30° = 0.50, cos 30° = 0.87). What is the tension in each rope?`,
    options: [r`50 N`, r`58 N`, r`200 N`, r`100 N`],
    correctAnswer: 3,
    explanation: r`Only the vertical components hold the sign: 2T sin 30° = 100 N, so T = 100 N. Each rope carries as much as the whole weight because the ropes are so flat. Getting 50 N assumes the ropes are vertical, 58 N uses the cosine for the vertical component, and 200 N forgets that two ropes share the load.`,
  },
  [r`Gravitation: {{c1::$F = Gm_1m_2/r^2$}}, where $r$ is measured {{c1::center to center}}.`]: {
    question: r`A probe weighs 800 N on Earth's surface. What is the gravitational force on it when it is at an altitude equal to one Earth radius above the surface?`,
    options: [r`100 N`, r`200 N`, r`400 N`, r`800 N`],
    correctAnswer: 1,
    explanation: r`The distance in the law is measured from Earth's center, so at an altitude of one radius the probe is 2 radii away, twice as far as at the surface. Inverse-square gives 800/4 = 200 N. Getting 400 N halves the force instead of quartering it, 800 N ignores the change, and 100 N divides by 8, more than doubling the distance allows.`,
  },
  [r`For a vector at angle theta from the x-axis, $V_x =$ {{c1::$V\cos\theta$}} and $V_y =$ {{c1::$V\sin\theta$}}.`]: {
    question: r`A 100 N force points 30° away from the vertical y-axis (sin 30° = 0.50, cos 30° = 0.87). What is its horizontal x-component?`,
    options: [r`50 N`, r`58 N`, r`87 N`, r`100 N`],
    correctAnswer: 0,
    explanation: r`The angle is measured from the y-axis, so cosine goes with y and sine with x: Fₓ = 100 × sin 30° = 50 N. The 87 N answer applies cosine to x out of habit, which is right only when the angle is measured from the x-axis. Getting 58 N uses the tangent, and 100 N is the whole force.`,
  },
  [r`Torque equals {{c1::$rF\sin\theta$}}, with $r$ measured from {{c1::the pivot to the point where the force acts}}.`]: {
    question: r`A door is 0.9 m wide. A person pushes with 20 N at a point 0.6 m from the hinges, at 30° to the door's surface (sin 30° = 0.50, cos 30° = 0.87). What torque does the push produce about the hinges?`,
    options: [r`9 N·m`, r`12 N·m`, r`6 N·m`, r`10.4 N·m`],
    correctAnswer: 2,
    explanation: r`τ = rF sin θ with r taken from the hinges to where the force is applied: 0.6 × 20 × 0.50 = 6 N·m. Using the full 0.9 m width for r gives 9 N·m, leaving out the angle gives 12 N·m, and using the cosine, the component along the door that produces no turning, gives 10.4 N·m.`,
  },
  [r`On an incline, which weight component drives sliding and which sets the normal force?`]: {
    question: r`A 10 kg box slides down a ramp inclined at 60° (sin 60° = 0.87, cos 60° = 0.50) with μk = 0.20. Taking g = 10 m/s², what is the kinetic friction force on the box?`,
    options: [r`17 N`, r`10 N`, r`20 N`, r`50 N`],
    correctAnswer: 1,
    explanation: r`Friction depends on the normal force, and that is set by the component of weight pressing into the ramp: N = mg cos θ = 100 × 0.50 = 50 N, so f = 0.20 × 50 = 10 N. Using the sine, the component that drives the sliding, gives 17 N. Using the full weight gives 20 N, and 50 N is the normal force itself.`,
  },
  [r`Why is a car at constant speed on a circular track not in equilibrium?`]: {
    question: r`A 1200 kg car travels around a level circular track of radius 50 m at a constant 10 m/s. What is the net force on the car?`,
    options: [r`Zero net force, since the speed stays constant`, r`2400 N, pointing away from the center of the track`, r`2400 N, pointing forward along the car's motion`, r`2400 N, pointing toward the center of the track`],
    correctAnswer: 3,
    explanation: r`The car's direction keeps changing, so it accelerates toward the center at v²/r = 2 m/s² and needs a net inward force of 1200 × 2 = 2400 N. Constant speed is not constant velocity, so the net force is not zero. An outward force would curve the path the other way, and a forward net force would make the car speed up.`,
  },
  [r`What sets the maximum speed for a car rounding a flat curve?`]: {
    question: r`On a flat curve of radius 80 m the coefficient of static friction between tires and road is 0.50 (g = 10 m/s²). What is the top speed without skidding for a 1000 kg car and for a 3000 kg truck on the same tires?`,
    options: [r`20 m/s for the car and 12 m/s for the truck`, r`20 m/s for the car and 35 m/s for the truck`, r`20 m/s for the car and 20 m/s for the truck`, r`40 m/s for the car and 40 m/s for the truck`],
    correctAnswer: 2,
    explanation: r`Friction supplies the centripetal force: μmg = mv²/r, so v = √(μgr) = √(0.50 × 10 × 80) = 20 m/s. Mass cancels, so both vehicles share the limit. A lower limit for the truck assumes its extra mass is harder to turn, a higher one assumes its extra friction is not needed, and 40 m/s leaves out the coefficient of friction.`,
  },
  [r`What is the minimum speed at the top of a vertical loop to maintain contact?`]: {
    question: r`A bucket of water is swung in a vertical circle of radius 0.90 m. Taking g = 10 m/s², what is the slowest speed at the top of the circle that keeps the water in the bucket?`,
    options: [r`3 m/s`, r`9 m/s`, r`4.2 m/s`, r`0.3 m/s`],
    correctAnswer: 0,
    explanation: r`At the minimum speed the bucket pushes with zero force and gravity alone is the centripetal force: mg = mv²/r, so v = √(gr) = √9 = 3 m/s. Leaving off the square root gives 9, using √(2gr) from an energy formula gives 4.2 m/s, and dividing r by g gives 0.3.`,
  },
  [r`The centripetal force does {{c1::zero}} work in uniform circular motion.`]: {
    question: r`A 2 kg puck on a frictionless table moves at 3 m/s in a circle of radius 0.5 m on a string whose tension is 36 N. How much work does the tension do on the puck during a quarter of a revolution?`,
    options: [r`9 J`, r`0 J`, r`18 J`, r`28 J`],
    correctAnswer: 1,
    explanation: r`The tension always points along the string toward the center, at 90° to the puck's velocity, so it does zero work, which is why the puck's speed never changes. Getting 28 J multiplies the tension by the arc length, 18 J multiplies it by the radius, and 9 J is the puck's kinetic energy.`,
  },
  [r`How should you choose the pivot point in a static equilibrium problem?`]: {
    question: r`A uniform beam is hinged to a wall at its left end and held level by a vertical cable at its right end. The hinge force and the cable tension are both unknown. Which pivot gives a torque equation whose only unknown is the cable tension?`,
    options: [r`The right end, where the cable is attached to the beam`, r`The center of the beam, where its weight is taken to act`, r`Any point: the torque equation is the same for every pivot`, r`The left end, where the hinge force acts on the beam`],
    correctAnswer: 3,
    explanation: r`A force applied at the pivot has zero lever arm and drops out of the torque equation. Putting the pivot at the hinge removes the hinge force and leaves only the tension and the known weight. A pivot at the cable removes the tension itself, a pivot at the center keeps both unknowns, and although every pivot is valid, the equations they give are not the same.`,
  },
  [r`What condition keeps an object from tipping over?`]: {
    question: r`A person stands with feet together and leans forward from the ankles with the body kept straight. The person begins to topple forward when the vertical line through the center of mass passes:`,
    options: [r`just in front of the toes`, r`just in front of the heels`, r`just in front of the ankles`, r`through the middle of the feet`],
    correctAnswer: 0,
    explanation: r`An object tips once the vertical line through its center of mass falls outside the base of support, and the front edge of this base is the toes. With the line in front of the heels or ankles, or through mid-foot, it is still inside the base, so the floor can still supply a balancing torque.`,
  },
  [r`True weight is {{c1::$mg$}}, while apparent weight equals {{c1::the normal force}}.`]: {
    question: r`A 60 kg rider stands on a scale in an elevator that is moving upward and slowing down at 2 m/s². Taking g = 10 m/s², what does the scale read?`,
    options: [r`600 N`, r`720 N`, r`480 N`, r`120 N`],
    correctAnswer: 2,
    explanation: r`Moving up while slowing means the acceleration points downward, so N = m(g − a) = 60 × 8 = 480 N. The 720 N answer uses the direction of motion instead of the direction of acceleration. 600 N is the true weight, which the scale shows only at zero acceleration, and 120 N is just ma.`,
  },
  [r`An inclined plane's ideal mechanical advantage equals {{c1::incline length divided by height}}.`]: {
    question: r`A frictionless ramp is 10 m long and rises 2 m. What is its ideal mechanical advantage, and what force along the ramp moves a 500 N cart up it at constant speed?`,
    options: [r`MA of 0.2; a force of 2500 N`, r`MA of 5; a force of 500 N`, r`MA of 20; a force of 25 N`, r`MA of 5; a force of 100 N`],
    correctAnswer: 3,
    explanation: r`The ideal mechanical advantage is length over height, 10/2 = 5, so the force needed is 500/5 = 100 N. Inverting the ratio gives 0.2 and a force larger than the weight. A force of 500 N is what lifting straight up needs, and 20 comes from multiplying length by height.`,
  },
  [r`Fixed pulley versus movable pulley: what does each accomplish?`]: {
    question: r`A 400 N load hangs from a single movable pulley that is held by two supporting rope segments. Ignoring friction and the pulley's weight, what pull raises the load at constant speed, and how much rope is pulled to raise it 1 m?`,
    options: [r`200 N of pull and 1 m of rope`, r`200 N of pull and 2 m of rope`, r`400 N of pull and 1 m of rope`, r`100 N of pull and 4 m of rope`],
    correctAnswer: 1,
    explanation: r`Two rope segments share the load, so each carries 200 N, and both must shorten by 1 m, so 2 m of rope is pulled. The work is the same either way: 200 × 2 = 400 × 1. Halving the force without doubling the rope would reduce the work. 400 N and 1 m describes a fixed pulley, and 100 N and 4 m needs four supporting segments.`,
  },
  [r`Why do muscles insert close to joints if that demands more force?`]: {
    question: r`The biceps attaches 3 cm from the elbow and the hand is 30 cm from the elbow. When the biceps shortens by 1 cm, about how far does the hand move, and how does the muscle force compare with a load in the hand?`,
    options: [r`10 cm, and the muscle force is one tenth of the load`, r`0.1 cm, and the muscle force is 10 times the load`, r`10 cm, and the muscle force is 10 times the load`, r`0.1 cm, and the muscle force is one tenth of the load`],
    correctAnswer: 2,
    explanation: r`The hand is 10 times farther from the pivot, so it sweeps 10 times as far and as fast as the insertion point: about 10 cm. The price is force: torque balance makes the muscle force 10 times the load. A lever cannot multiply both distance and force, and the 0.1 cm answers put the gain in range at the wrong end.`,
  },
  [r`For a satellite in circular orbit, what supplies centripetal force and what follows?`]: {
    question: r`A 500 kg satellite circles a planet at radius r with speed 8 km/s. A 2000 kg satellite circles the same planet at radius 4r. What is the speed of the second satellite?`,
    options: [r`4 km/s`, r`2 km/s`, r`8 km/s`, r`16 km/s`],
    correctAnswer: 0,
    explanation: r`Setting gravity equal to the centripetal force gives v = √(GM/r), with the satellite's own mass cancelled. At 4 times the radius the speed is 8/√4 = 4 km/s: higher orbits are slower. Getting 2 km/s divides by 4 without the square root, 8 km/s ignores the radius, and 16 km/s wrongly scales the speed up with radius or satellite mass.`,
  },
  [r`A patient carries a heavy suitcase in the right hand. Why does a cane in the LEFT hand reduce right hip joint force?`]: {
    question: r`A patient has a painful LEFT hip and no load in either hand. In which hand should a cane be held to lower the force on that hip joint, and why?`,
    options: [r`Left hand: its push acts close to the left hip, so the abductors need less force`, r`Right hand: its push acts far from the left hip, so the abductors need less force`, r`Right hand: it carries half of the body weight, so the abductors need no force`, r`Left hand: it carries half of the body weight, so the abductors need no force`],
    correctAnswer: 1,
    explanation: r`When standing on the left leg, the left abductors must balance the torque of body weight about the left hip, and their pull compresses the joint. A cane on the right pushes up far from that pivot, so a small force gives a large helping torque and the abductors can relax. A cane on the left has almost no lever arm about the left hip, and a cane takes only a small part of body weight.`,
  },
  [r`Centripetal acceleration must carry units of m/s$^2$, so of $v^2/r$ and $v/r^2$ only {{c1::$v^2/r$}} is possible.`]: {
    question: r`A student cannot remember whether centripetal acceleration written with angular speed ω (in s⁻¹) and radius r (in m) is ω²r or ωr². What does a unit check show?`,
    options: [r`ωr², because s⁻¹ × m² gives m/s²`, r`ω²r, because s⁻¹ × m gives m/s²`, r`ωr², because s⁻² × m gives m/s²`, r`ω²r, because s⁻² × m gives m/s²`],
    correctAnswer: 3,
    explanation: r`An acceleration must come out in m/s². ω²r has units s⁻² × m = m/s², so it is possible. ωr² has units s⁻¹ × m² = m²/s, which is not an acceleration. The other statements name an expression but attach units that do not belong to it.`,
  },
  [r`Why does lifting a box with a rounded back produce enormous compressive force on the lumbar spine?`]: {
    question: r`A person bends forward to lift a box. The combined weight of the box and upper body, 500 N, acts 40 cm in front of the pivot at the base of the spine. The back muscles pull 5 cm behind the pivot. What muscle force balances the load?`,
    options: [r`4000 N`, r`3500 N`, r`500 N`, r`63 N`],
    correctAnswer: 0,
    explanation: r`Torques about the pivot must balance: F × 5 cm = 500 N × 40 cm, so F = 4000 N, eight times the load, and this force compresses the lower spine. Getting 63 N inverts the lever-arm ratio, 500 N assumes equal arms, and 3500 N wrongly subtracts the muscle's arm from the load's arm.`,
  },
  [r`At fixed mass and radius, a plot of centripetal force versus $v^2$ is a straight line of slope {{c1::$m/r$}}.`]: {
    question: r`A stopper is whirled in a circle of radius 0.50 m. A graph of the centripetal force against v² is a straight line through the origin and through the point (4 m²/s², 16 N). What is the stopper's mass?`,
    options: [r`0.5 kg`, r`4 kg`, r`2 kg`, r`8 kg`],
    correctAnswer: 2,
    explanation: r`F = (m/r)v², so the slope is m/r. The slope is 16/4 = 4 kg/m, and m = slope × r = 4 × 0.50 = 2 kg. Reading the slope itself as the mass gives 4 kg, dividing by r instead of multiplying gives 8 kg, and 0.5 is just the radius.`,
  },
  [r`A centrifuge rotor of radius 4 cm spins at 3000 rpm. Roughly how many g does the sample experience?`]: {
    question: r`A small centrifuge spins at 600 rpm, and a sample sits 10 cm from the axis. Taking π² ≈ 10 and g = 10 m/s², roughly what acceleration does the sample experience?`,
    options: [r`About 0.6 g`, r`About 4 g`, r`About 400 g`, r`About 40 g`],
    correctAnswer: 3,
    explanation: r`600 rpm is 10 rev/s, so ω = 2π × 10 ≈ 63 rad/s and ω² ≈ 4000 s⁻². Then a = ω²r ≈ 4000 × 0.10 = 400 m/s², about 40 g. Getting 400 g forgets to divide by g, 4 g drops a factor of ten along the way, and 0.6 g uses ωr, a speed, instead of ω²r.`,
  },
  [r`Is the outward push you feel on a spinning ride a real force?`]: {
    question: r`A car turns sharply to the left and a passenger slides to the right across the seat. Viewed from the ground, why does the passenger slide relative to the car?`,
    options: [r`A centrifugal force pushes the body away from the center`, r`Too little inward force acts, so the body goes nearly straight`, r`Seat friction pushes the body away from the center`, r`The centripetal force on the body points to the right`],
    correctAnswer: 1,
    explanation: r`From the ground, the passenger's body tends to continue in a straight line while the car turns underneath it, because the seat cannot supply enough inward force until the door does. No real force pushes outward: the centrifugal force appears only in the turning car's frame. Friction from the seat acts inward, and a centripetal force always points toward the center, which is to the left.`,
  },
  [r`Over exactly one full revolution, average velocity is {{c1::zero}} while average speed is {{c1::$2\pi r/T$}}.`]: {
    question: r`A carousel horse is 5 m from the axis and completes one full turn in 10 s. Taking π ≈ 3.1, what are the horse's average speed and average velocity over that one turn?`,
    options: [r`Average speed zero; average velocity 3.1 m/s`, r`Average speed 3.1 m/s; average velocity 3.1 m/s`, r`Average speed 3.1 m/s; average velocity zero`, r`Average speed 1.0 m/s; average velocity zero`],
    correctAnswer: 2,
    explanation: r`Average speed is path length over time: 2π(5)/10 ≈ 3.1 m/s. Average velocity is displacement over time, and after a full turn the horse is back where it started, so it is zero. Giving both as 3.1 m/s ignores that distinction, swapping them reverses the definitions, and 1.0 m/s uses the diameter in place of the circumference.`,
  },
  [r`Rising onto tiptoe makes the foot a {{c1::second-class}} lever with the pivot at {{c1::the toes}} and the load at the ankle.`]: {
    question: r`When a person rises onto tiptoe, the foot works as a lever. Which tool has the same arrangement of pivot, load and effort?`,
    options: [r`A wheelbarrow: wheel at one end, load in the middle`, r`A seesaw: pivot in the middle, riders at both ends`, r`Tweezers: joined at one end, squeezed in the middle`, r`Scissors: pivot in the middle, hands at one end`],
    correctAnswer: 0,
    explanation: r`On tiptoe the pivot is at the toes, the load (body weight) comes down at the ankle, and the effort is the calf pulling up at the heel: load between pivot and effort, a second-class lever, like a wheelbarrow. The seesaw and scissors have the pivot in the middle (first class), and tweezers have the effort in the middle (third class).`,
  },
  [r`Why can molars generate far more bite force than incisors?`]: {
    question: r`A jaw muscle pulls with 300 N at a point 4 cm from the jaw joint. A molar is 6 cm from the joint and an incisor is 12 cm from it. What bite force can each tooth deliver?`,
    options: [r`100 N at the molar and 200 N at the incisor`, r`450 N at the molar and 900 N at the incisor`, r`300 N at the molar and 300 N at the incisor`, r`200 N at the molar and 100 N at the incisor`],
    correctAnswer: 3,
    explanation: r`The muscle's torque about the joint is 300 × 4 = 1200 N·cm. Dividing by each tooth's distance gives 1200/6 = 200 N at the molar and 1200/12 = 100 N at the incisor: the tooth nearer the pivot bites harder. The reversed pair gives the far tooth the advantage, 450 N and 900 N invert the lever-arm ratios, and equal forces ignore the lever arms.`,
  },
  [r`Torque plotted against the angle between $r$ and $F$ peaks at {{c1::90 degrees}} and falls to zero at {{c1::0 and 180 degrees}}.`]: {
    question: r`A tendon pulls with a constant 100 N at a point 0.05 m from a joint. As the limb moves, the angle between the bone and the tendon's pull goes from 30° to 90° to 150° (sin 30° = sin 150° = 0.50). What is the torque at these three angles?`,
    options: [r`2.5, 5.0, then 7.5 N·m`, r`2.5, 5.0, then 2.5 N·m`, r`4.3, 0, then 4.3 N·m`, r`5.0, 5.0, then 5.0 N·m`],
    correctAnswer: 1,
    explanation: r`τ = rF sin θ = 5.0 × sin θ, which peaks at 90° and falls off equally on either side: 2.5, 5.0, 2.5 N·m. A torque that keeps climbing to 7.5 treats it as proportional to the angle. The set with zero at 90° uses the cosine, and three equal values ignore the angle.`,
  },
  [r`Why does a two-pan balance read the same on the Moon while a spring scale does not?`]: {
    question: r`On Earth (g = 10 m/s²) a rock is matched by 4 kg of standard masses on a two-pan balance and reads 40 N on a spring scale. Both instruments are taken to a planet where g = 5 m/s². What do they show there?`,
    options: [r`Balance 4 kg, spring scale 20 N`, r`Balance 2 kg, spring scale 20 N`, r`Balance 4 kg, spring scale 40 N`, r`Balance 2 kg, spring scale 40 N`],
    correctAnswer: 0,
    explanation: r`The balance compares the rock with standard masses, and the weaker gravity acts equally on both pans, so it still shows 4 kg. The spring scale reads the force mg = 4 × 5 = 20 N. A balance reading of 2 kg assumes mass changes with location, and a spring reading of 40 N assumes weight does not.`,
  },
  [r`Relative centrifugal force compares {{c1::$\omega^2 r$}} with {{c1::$g$}}, so it is reported in multiples of gravity.`]: {
    question: r`A protocol reaches a relative centrifugal force of 1000 × g. The sample is moved to a rotor with half the radius and spun at twice the rpm. What is the new relative centrifugal force?`,
    options: [r`500 × g`, r`1000 × g`, r`2000 × g`, r`4000 × g`],
    correctAnswer: 2,
    explanation: r`RCF is ω²r/g. Doubling the rotation rate multiplies it by 4, and halving the radius multiplies it by ½, so the result is 1000 × 4 × ½ = 2000 × g. Getting 1000 × g treats speed and radius as equally weighted, 4000 × g ignores the radius change, and 500 × g ignores the speed change.`,
  },
  [r`A 70 kg adult weighs about {{c1::700 N}}, so each foot carries roughly {{c1::350 N}} in quiet standing.`]: {
    question: r`A 50 kg patient stands still with weight shared evenly on both feet, then shifts to stand on one leg. Taking g = 10 m/s², what upward force does the floor exert on the standing foot before and after the shift?`,
    options: [r`25 N, then 50 N`, r`250 N, then 500 N`, r`500 N, then 1000 N`, r`250 N, then 250 N`],
    correctAnswer: 1,
    explanation: r`The patient weighs 50 × 10 = 500 N. Shared evenly, each foot carries 250 N. On one leg that foot carries all 500 N. The 25 N and 50 N answers leave out g, 500 N then 1000 N doubles the weight for no reason, and 250 N both times forgets that one foot must now hold the whole weight.`,
  },
  [r`A ball rolls without slipping. What links $v$ and $\omega$, and does static friction do work?`]: {
    question: r`A wheel of radius 0.30 m rolls without slipping along level ground at 6 m/s. What is its angular speed, and what does static friction at the contact point do to the wheel's mechanical energy?`,
    options: [r`1.8 rad/s, and friction leaves the energy unchanged`, r`20 rad/s, and friction steadily removes energy`, r`1.8 rad/s, and friction steadily removes energy`, r`20 rad/s, and friction leaves the energy unchanged`],
    correctAnswer: 3,
    explanation: r`Rolling without slipping means v = ωr, so ω = 6/0.30 = 20 rad/s. The contact point is momentarily at rest, so static friction acts through no distance and does no work. The 1.8 answers multiply v by r instead of dividing, and energy is drained only by kinetic friction, when the surfaces slide.`,
  },
  [r`A diver tucks mid-somersault. What is conserved, and what happens to spin rate and rotational kinetic energy?`]: {
    question: r`A student spins on a frictionless stool at 2 rad/s with arms out, where the moment of inertia is 6 kg·m². Pulling the arms in lowers it to 2 kg·m². What are the new angular speed and the change in rotational kinetic energy?`,
    options: [r`ω = 6 rad/s, and KE stays fixed at 12 J`, r`ω = 3.5 rad/s, and KE stays fixed at 12 J`, r`ω = 6 rad/s, and KE rises from 12 J to 36 J`, r`ω = 6 rad/s, and KE falls from 12 J to 4 J`],
    correctAnswer: 2,
    explanation: r`No external torque acts, so L = Iω = 12 kg·m²/s is conserved and ω = 12/2 = 6 rad/s. KE = ½Iω² goes from ½(6)(4) = 12 J to ½(2)(36) = 36 J, with the extra energy supplied by the muscles that pull the arms in. The 3.5 rad/s answer conserves energy instead of angular momentum, and the others get ω right but the energy wrong.`,
  },
  [r`Torque has units of {{c1::N$\cdot$m}}, so of $Fr$, $F/r$, and $Fr^2$ only {{c1::$Fr$}} can be a torque.`]: {
    question: r`A smudged formula sheet leaves three candidates for the torque of a rod's weight W (in N) about one end of a rod of length L (in m): WL/2, W/(2L) and WL²/2. Which one can be a torque?`,
    options: [r`WL/2, since it has units of N·m`, r`W/(2L), since it has units of N/m`, r`WL²/2, since it has units of N·m²`, r`WL/2, since it has units of N/m`],
    correctAnswer: 0,
    explanation: r`Torque is force times distance, so it must carry N·m. WL/2 does, and the factor of ½ has no units. W/(2L) is in N/m, which is the unit of a spring constant, and WL²/2 is in N·m², so neither can be a torque. The last statement picks the right expression but gives it the wrong units.`,
  },
  [r`A ball on a string swings in a horizontal circle (conical pendulum). What does each component of tension do?`]: {
    question: r`A 0.40 kg ball on a string moves in a horizontal circle with the string at 37° from the vertical (sin 37° = 0.60, cos 37° = 0.80). Taking g = 10 m/s², what are the tension and the centripetal force?`,
    options: [r`Tension 4 N; centripetal force 3 N`, r`Tension 5 N; centripetal force 4 N`, r`Tension 3.2 N; centripetal force 1.9 N`, r`Tension 5 N; centripetal force 3 N`],
    correctAnswer: 3,
    explanation: r`The vertical part of the tension balances the weight: T cos 37° = 4 N, so T = 5 N. The horizontal part is the centripetal force: T sin 37° = 5 × 0.60 = 3 N. A tension of 4 N sets it equal to the weight, 3.2 N multiplies the weight by the cosine instead of dividing, and a centripetal force of 4 N uses the vertical component.`,
  },
  [r`A cart is released from height $h$ and runs a vertical loop of radius $R$. Which two relations must be combined?`]: {
    question: r`A cart starts from rest on a frictionless track and must get around a vertical loop of radius 4 m without leaving the track at the top. What is the lowest starting height above the bottom of the loop?`,
    options: [r`8 m`, r`10 m`, r`12 m`, r`4 m`],
    correctAnswer: 1,
    explanation: r`At the top the cart needs v² = gR. Energy conservation gives mgh = mg(2R) + ½mv² = mg(2R) + ½mgR, so h = 2.5R = 10 m. Starting at 8 m, the height of the loop's top, would leave zero speed there and the cart would fall. 4 m reaches only halfway up, and 12 m is more than the minimum.`,
  },
}
